import {Soundtrack} from './audio.js';
import {paintWorld,paintCraft,paintHazards,paintSpeedTrails,paintScreenGrade} from './visuals.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),sound=new Soundtrack();
let run=createRun(),state='menu',last=0,view={w:1,h:1,scale:1,x:0,y:0},effects=[],flash=0,noticeUntil=0,phase='',reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,pointer=null,target=null,bank=0,menuTime=0,started=false;
