let records={},progress={};try{records=JSON.parse(localStorage.getItem('edm-dodge-reli-records')||'{}');}catch{}try{progress=JSON.parse(localStorage.getItem('edm-dodge-reli-progress-v2')||'{}');}catch{}function showBest(){const key=scoreKey($('mission').value,$('difficulty').value);const n=records[key]||($('mission').value==='neon'?records[$('difficulty').value]:0)||0;const medal=getRecord(progress,$('mission').value,$('difficulty').value).stars;$('best').textContent=(n?'BEST '+Math.floor(n).toLocaleString():'BEST —')+'  '+('★'.repeat(medal)+'☆'.repeat(3-medal));}showBest();$('difficulty').onchange=showBest;$('mission').onchange=()=>{const m=missionFor($('mission').value);$('missionInfo').textContent=m.subtitle;$('missionNumber').textContent='MISSION '+m.number;$('missionTitle').textContent=m.title;const g=missionGoals(m.id);$('missionGoals').textContent='3 STARS · SURVIVE / '+g.near+' NEAR MISSES / '+g.salvage+' SALVAGE';document.documentElement.style.setProperty('--cyan',m.accent);showBest();};$('mission').onchange();$('motion').textContent=reduced?'FX LOW':'FX ON';
function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);view.w=r.width;view.h=r.height;view.scale=Math.min(r.width/W,r.height/H);view.x=(r.width-W*view.scale)/2;view.y=(r.height-H*view.scale)/2;ctx.setTransform(dpr,0,0,dpr,0,0);}new ResizeObserver(resize).observe(canvas);
function uiFlight(on){for(const id of ['hud','timeline','flightBottom','pause'])$(id).hidden=!on;}
function announce(text,duration=2){$('notice').textContent=text;noticeUntil=run.t+duration;}
async function launch(){if(started)return;started=true;$('start').disabled=true;$('retry').disabled=true;$('error').hidden=true;try{await sound.start($('mission').value);run=createRun($('mission').value);run.hp=$('difficulty').value==='rookie'?5:$('difficulty').value==='ace'?1:3;run.maxHp=run.hp;$('missionName').textContent=missionFor(run.mission).title;effects=[];phase='';target=null;pointer=null;keys.clear();state='playing';last=0;for(const id of ['menu','result','paused'])$(id).hidden=true;uiFlight(true);announce('DRAG TO FLY · SPACE / DASH TO PHASE',4);}catch(e){sound.stop();state='menu';$('menu').hidden=false;$('error').hidden=false;$('error').textContent='Δεν ξεκίνησε ο ήχος. Άνοιξε το παιχνίδι σε Safari / Chrome και πάτησε ξανά Launch.';}finally{started=false;$('start').disabled=false;$('retry').disabled=false;}}
async function pauseGame(){if(state!=='playing')return;state='paused';keys.clear();pointer=null;target=null;$('paused').hidden=false;$('pause').textContent='▶';try{await sound.pause();}catch{}}
async function resumeGame(){if(state!=='paused')return;try{await sound.resume();if(state!=='paused')return;state='playing';last=0;$('paused').hidden=true;$('pause').textContent='Ⅱ';}catch{}}
function menu(){state='menu';sound.stop();keys.clear();pointer=null;target=null;for(const id of ['result','paused'])$(id).hidden=true;$('menu').hidden=false;$('notice').textContent='';$('pause').textContent='Ⅱ';uiFlight(false);showBest();}
function end(){state='result';sound.stop();uiFlight(false);$('notice').textContent='';$('result').hidden=false;const won=run.finished;$('resultLabel').textContent=won?'MISSION COMPLETE / FLIGHT REPORT':'SIGNAL LOST / FLIGHT REPORT';$('resultTitle').innerHTML=won?'DROP<br><em>SURVIVED.</em>':'ONE MORE<br><em>FLIGHT.</em>';$('rank').textContent=won?rank(run):'—';$('finalScore').textContent=Math.floor(run.score).toLocaleString();$('finalStats').textContent=run.near+' near misses · '+run.bestCombo+' max flow · '+run.pickups+' salvage';$('resultTip').textContent=won?'Έμεινες στη ροή για δύο λεπτά. Μπορείς να το κάνεις με περισσότερο style;':'Διάβασε τα κενά. Τα κόκκινα lasers προειδοποιούν πριν χτυπήσουν. Το phase dash σε προστατεύει για λίγο.';const evaluation=evaluateMission(run);$('missionStars').textContent=evaluation.stars+' / 3 STARS  '+('★'.repeat(evaluation.stars)+'☆'.repeat(3-evaluation.stars));$('resultObjectives').textContent=evaluation.objectives.map(o=>(o.met?'✓ ':'○ ')+o.label).join('  ·  ');progress=recordMission(progress,run.mission,$('difficulty').value,run.score,evaluation.stars);try{localStorage.setItem('edm-dodge-reli-progress-v2',JSON.stringify(progress));}catch{}const mode=scoreKey(run.mission,$('difficulty').value);records[mode]=Math.max(records[mode]||0,run.score);try{localStorage.setItem('edm-dodge-reli-records',JSON.stringify(records));}catch{}showBest();}
function useDash(){if(state==='playing'&&dash(run)){sound.effect('dash');announce('PHASE SHIFT',.55);flash=.12;}}
$('start').onclick=launch;$('retry').onclick=launch;$('resume').onclick=resumeGame;$('pause').onclick=()=>state==='paused'?resumeGame():pauseGame();$('exit').onclick=menu;$('hangar').onclick=menu;$('dash').onpointerdown=e=>{e.preventDefault();useDash();};$('mute').onclick=()=>{$('mute').textContent=sound.mute()?'SOUND OFF':'SOUND ON';};$('motion').onclick=()=>{reduced=!reduced;$('motion').textContent=reduced?'FX LOW':'FX ON';};
addEventListener('keydown',e=>{if(['playing','paused'].includes(state)&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'||e.code==='KeyP'){if(!e.repeat)state==='paused'?resumeGame():pauseGame();return;}if(e.code==='Space'&&!e.repeat)useDash();keys.add(e.code);});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',pauseGame);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseGame();});
const point=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left-view.x)/view.scale,y:(e.clientY-r.top-view.y)/view.scale};};
canvas.addEventListener('pointerdown',e=>{if(state!=='playing'||pointer)return;e.preventDefault();const q=point(e);pointer={id:e.pointerId,x:q.x,y:q.y,craftX:run.player.x,craftY:run.player.y};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId||state!=='playing')return;const q=point(e);target={x:pointer.craftX+(q.x-pointer.x)*1.15,y:pointer.craftY+(q.y-pointer.y)*1.15};});
function release(e){if(pointer?.id===e.pointerId){pointer=null;target=null;}}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
function burst(x,y,color,count=20){if(reduced)return;for(let i=0;i<count;i++)effects.push({x,y,vx:Math.cos(i*2.399)* (60+i*5),vy:Math.sin(i*2.399)*(60+i*5),life:.6,max:.6,color});}
function event(type,h){if(type==='boss'){sound.effect('dash');announce('HUNTER CARRIER INBOUND',2.2);}if(type==='pickup'){sound.effect('near');burst(run.player.x,run.player.y,'#a0ff9d',24);announce(h,1.3);}if(type==='near'){sound.effect('near');burst(run.player.x,run.player.y,'#75ffef',10);announce('NEAR MISS +'+100*(1+Math.min(4,Math.floor(run.combo/5))),.7);}if(type==='hit'){sound.effect('hit');burst(run.player.x,run.player.y,'#ff764e',28);flash=.45;announce('HULL HIT',.8);}if(type==='dead'||type==='complete')end();}
function path(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
